package com.tenora365.controller;
import com.tenora365.entity.*;import com.tenora365.repository.*;import com.tenora365.tenant.TenantContext;import com.tenora365.service.AuditService;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.math.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api") public class ApiController{final StudentRepository students;final TeacherRepository teachers;final SchoolRepository schools;final UserRepository users;final FeePaymentRepository fees;final ModuleRecordRepository modules;final AuditLogRepository audits;final AuditService audit;ApiController(StudentRepository s,TeacherRepository t,SchoolRepository sc,UserRepository u,FeePaymentRepository f,ModuleRecordRepository m,AuditLogRepository a,AuditService au){students=s;teachers=t;schools=sc;users=u;fees=f;modules=m;audits=a;audit=au;}Long tenant(){Long id=TenantContext.get();if(id==null)throw new IllegalStateException("Tenant context missing");return id;}School school(){return schools.findById(tenant()).orElseThrow();}
@GetMapping("/dashboard")Map<String,Object> dash(){Long id=tenant();return Map.of("students",students.countBySchoolId(id),"teachers",teachers.countBySchoolId(id),"feesCollected",Optional.ofNullable(fees.sumPaid(id)).orElse(BigDecimal.ZERO),"school",school().getName());}
@GetMapping("/students")List<Student> students(){return students.findBySchoolIdOrderByIdDesc(tenant());}@PostMapping("/students")Student add(@Valid @RequestBody Student x,HttpServletRequest r){x.setId(null);x.setSchool(school());var s=students.save(x);audit.log(null,"CREATE","STUDENT",String.valueOf(s.getId()),s,r);return s;}@PutMapping("/students/{id}")Student update(@PathVariable Long id,@RequestBody Student x,HttpServletRequest r){var s=students.findByIdAndSchoolId(id,tenant()).orElseThrow();x.setId(id);x.setSchool(s.getSchool());var out=students.save(x);audit.log(null,"UPDATE","STUDENT",String.valueOf(id),x,r);return out;}@DeleteMapping("/students/{id}")void delete(@PathVariable Long id,HttpServletRequest r){var s=students.findByIdAndSchoolId(id,tenant()).orElseThrow();students.delete(s);audit.log(null,"DELETE","STUDENT",String.valueOf(id),null,r);}
@GetMapping("/teachers")List<Teacher> teachers(){return teachers.findBySchoolIdOrderByIdDesc(tenant());}@PostMapping("/teachers")Teacher addTeacher(@RequestBody Teacher x){x.setId(null);x.setSchool(school());return teachers.save(x);}
@GetMapping("/fees")List<FeePayment> feeList(){return fees.findBySchoolIdOrderByIdDesc(tenant());}@PostMapping("/fees")FeePayment addFee(@RequestBody FeePayment x){x.setId(null);x.setSchool(school());x.setPaidOn(x.getPaidOn()==null?LocalDate.now():x.getPaidOn());x.setStatus(x.getStatus()==null?"PAID":x.getStatus());x.setReceiptNo(x.getReceiptNo()==null?"TR-"+System.currentTimeMillis():x.getReceiptNo());return fees.save(x);}
@GetMapping("/modules/{module}")List<ModuleRecord> list(@PathVariable String module){return modules.findBySchoolIdAndModuleOrderByIdDesc(tenant(),module.toUpperCase());}@PostMapping("/modules/{module}")ModuleRecord create(@PathVariable String module,@RequestBody String json){ModuleRecord r=new ModuleRecord();r.setSchool(school());r.setModule(module.toUpperCase());r.setDataJson(json);r.setRecordKey(UUID.randomUUID().toString());return modules.save(r);}@PutMapping("/modules/{module}/{id}")ModuleRecord update(@PathVariable String module,@PathVariable Long id,@RequestBody String json){var r=modules.findByIdAndSchoolId(id,tenant()).orElseThrow();r.setDataJson(json);r.setUpdatedAt(LocalDateTime.now());return modules.save(r);}@DeleteMapping("/modules/{module}/{id}")void remove(@PathVariable String module,@PathVariable Long id){var r=modules.findByIdAndSchoolId(id,tenant()).orElseThrow();modules.delete(r);}
@GetMapping("/audit")List<AuditLog> audit(){return audits.findTop100BySchoolIdOrderByCreatedAtDesc(tenant());}
}
